'use strict';
(function(){
const C=JourneyContent,txt=o=>L(o.en,o.pt),title=id=>L(...C.titles[id]),name=c=>C.isCurse(c)?txt(C.curses[c.type]):G.BY[c.type].name;
const stories={
 cofre:['A sealed chest whispers promises. Its lock may conceal treasure—or bind another traveler.','Um cofre selado sussurra promessas. A fechadura guarda um tesouro — ou prende mais um viajante.'],
 resgate:['A captive traveler asks for help. Buy their freedom or challenge the guards.','Um viajante aprisionado pede ajuda. Compre sua liberdade ou desafie os guardas.'],
 altar:['The altar can share a companion’s strength with the others. Choose what you surrender.','O altar divide a força de um companheiro entre os demais. Escolha o que entregar.'],
 caravana:['Tracks lead from an abandoned caravan into dangerous ground.','Pegadas levam de uma caravana abandonada para um terreno perigoso.'],
 mercador:['The merchant displays familiar contracts beside a sealed package. You may inspect the known recruit before paying.','O mercador exibe contratos conhecidos ao lado de um pacote selado. Você pode examinar o recruta antes de pagar.'],
 dojo:['An old technique promises swift progress, but practicing without a master invites an ill omen.','Uma técnica antiga promete progresso rápido, mas praticá-la sem mestre atrai um mau presságio.'],
 santuario:['Travelers will exchange two contracts for a relic. Any shortfall in their shop value is returned as gold.','Viajantes trocam dois contratos por uma relíquia. A diferença a menor no valor de loja volta em ouro.'],
 forja:['The unstable furnace reshapes relics. Without the smith’s help, your offering may be consumed.','A fornalha instável transforma relíquias. Sem a ajuda do ferreiro, sua oferta pode ser consumida.'],
 mestre:['A master offers a lesson—or a trial with a richer reward.','Um mestre oferece uma lição — ou uma prova com recompensa maior.'],
 aposta:['The dealer lays out the odds before a single coin changes hands. Payouts include the stake.','O crupiê revela as chances antes da aposta. O pagamento já inclui o valor apostado.'],
 contrabando:['The smuggler offers an experienced recruit. A free contract puts one of your relics at risk.','O contrabandista oferece um recruta experiente. Um contrato grátis coloca uma de suas relíquias em risco.'],
 despedida:['A broker buys a companion’s contract. Removing a curse requires a much more expensive service.','Um agente compra o contrato de um companheiro. Remover uma maldição exige um serviço bem mais caro.'],
 tesouro:['The guardians watch their treasure. Fight openly for a bonus or attempt a quieter approach.','Os guardiões vigiam o tesouro. Enfrente-os por um bônus ou tente uma abordagem discreta.'],
 profanado:['A relic waits in the desecrated sanctuary. Bargain for it—or risk waking its empowered guardians.','Uma relíquia aguarda no santuário profanado. Negocie por ela — ou arrisque despertar seus guardiões fortalecidos.'],
 ataque:['A caravan is under siege. Pay for a contract or intervene, risking a battle.','Uma caravana está cercada. Pague por um contrato ou intervenha, arriscando um combate.'],
 camara:['The champion names a price for the trophy. A challenge may earn gold as well.','O campeão dá um preço ao troféu. Um desafio também pode render ouro.'],
 reflexos:['The water can reflect a companion exactly, including their upgrades. An unprotected reflection may return a burden instead.','A água pode refletir um companheiro com seus upgrades. Sem proteção, o reflexo pode devolver um fardo.'],
 purificacao:['The fountain responds to the curses you carry. One may be washed away freely; a greater offering removes them all.','A fonte responde às maldições que você carrega. Uma pode ser lavada grátis; uma oferta maior remove todas.'],
 arena:['A first victory earns a purse. Only afterward must you decide whether to risk it on a stronger opponent.','A primeira vitória rende uma bolsa. Só depois você decide se a arrisca contra um adversário mais forte.'],
 sombras:['The bargainer always names the price. A curse will remain in this run’s deck until removed.','O negociador sempre revela o preço. Uma maldição fica no deck desta run até ser removida.'],
 banquete:['Hire the mercenaries to prepare your entire company for its next encounter. The effect lasts through every round of that encounter.','Contrate os mercenários para preparar toda a companhia para o próximo confronto. O efeito dura todas as rodadas desse confronto.'],
 chave:['A key promises a later reward. It occupies your mission inventory, never a card slot. The destination will be marked on the map.','Uma chave promete uma recompensa futura. Ela ocupa o inventário de missão, nunca uma vaga de carta. O destino será marcado no mapa.'],
 quest_end:['The key fits. Free the ally or claim the treasure, then continue into your chosen map node.','A chave encaixa. Liberte o aliado ou pegue o tesouro e continue para o node escolhido.']};
function sigil(id){const c=C.curses[id];return '<svg class="curse-sigil" viewBox="0 0 80 90" role="img" aria-label="'+esc(txt(c))+'"><path d="M40 4 72 23 68 64 40 85 12 64 8 23Z" fill="#251e37" stroke="#d9bd79" stroke-width="2"/><path d="m40 12 23 17-4 30-19 17-19-17-4-30Z" fill="none" stroke="#9e72bc"/>'+({burden:'<path d="M25 62 29 37h22l4 25Zm8-25v-7a7 7 0 0 1 14 0v7" fill="#9462aa" stroke="#eac2ec" stroke-width="3"/>',exhaustion:'<path d="m44 20-18 29h13l-4 22 21-32H42Z" fill="#eac2ec"/>',chains:'<g fill="none" stroke="#eac2ec" stroke-width="5" transform="rotate(35 40 45)"><rect x="31" y="19" width="18" height="30" rx="9"/><rect x="31" y="42" width="18" height="30" rx="9"/></g>',omen:'<path d="M18 45q22-27 44 0-22 27-44 0Z" fill="#9462aa" stroke="#eac2ec" stroke-width="3"/><path d="M40 34v22" stroke="#eac2ec" stroke-width="5"/>'}[id])+'</svg>';}
const portrait=P.portrait;P.portrait=function(id,...args){return C.curses[id]?sigil(id):portrait(id,...args);};
const face=cardFace;cardFace=function(c,action='hand',extra='',context){if(!C.isCurse(c))return face(c,action,extra,context);const d=C.curses[c.type];return '<button class="unit-card curse-card '+(S?.handFrozen&&action==='hand'?'frozen-card':'')+'" data-act="'+action+'" data-id="'+c.uid+'" '+extra+' aria-label="'+esc(txt(d)+'. '+L(d.enDesc,d.ptDesc))+'"><span class="curse-card-label">'+L('CURSE','MALDIÇÃO')+'</span><span class="portrait">'+sigil(c.type)+'</span><b class="card-name">'+esc(txt(d))+'</b><span class="curse-card-effect">'+esc(L(d.enDesc,d.ptDesc))+'</span><span class="curse-card-foot">'+(c.type==='chains'?L('Play · 1 energy','Jogar · 1 energia'):L('Run only','Só nesta run'))+'</span></button>';};
function curseDetail(c){const inHand=S?.phase==='prep'&&S.hand.includes(c.uid),d=C.curses[c.type];journeyPanel(txt(d),'<div class="curse-detail-symbol">'+sigil(c.type)+'</div><p>'+esc(L(d.enDesc,d.ptDesc))+'</p><p class="panel-hint">'+L('No traits, unit, fusion or upgrades. Discarding grants no energy and keeps the card in this run’s deck. Shop purification costs 40 gold per curse.','Sem traits, unidade, fusão ou upgrades. Descartar não concede energia e mantém a carta no deck desta run. Purificação na loja custa 40 ouros por maldição.')+'</p>',(inHand&&c.type==='chains'?metaButton('content-chain',L('Set aside · 1 energy','Afastar · 1 energia'),'data-id="'+c.uid+'" '+(S.energy<1?'disabled':''),'primary'):'')+(inHand?metaButton('content-discard',L('Discard · no energy','Descartar · sem energia'),'data-id="'+c.uid+'"'):'')+metaButton('close',L('Back','Voltar')));}
const oldDetail=detail;detail=function(c,...args){return C.isCurse(c)?curseDetail(c):oldDetail(c,...args);};
const relicMark=relicIcon;relicIcon=function(id){const icon={captain_standard:'banner',profane_idol:'crit',colossal_heart:'heart',dormant_sword:'sword',travelers_mirror:'deck'}[id];return icon?Icon(icon):relicMark(id);};
const fields={card:['Unit offered / duplicated','Unidade oferecida / duplicada'],upgrade:['Unit to upgrade','Unidade para melhorar'],target1:['First upgrade','Primeiro upgrade'],target2:['Second upgrade','Segundo upgrade'],curse:['Curse to remove','Maldição para remover'],relic:['Relic offered','Relíquia oferecida'],recruit:['Recruit','Recruta'],recruit2:['Second recruit (different)','Segundo recruta (diferente)'],rareRecruit:['Rare recruit · upgrade 1','Recruta raro · upgrade 1'],rewardRelic:['Relic reward','Relíquia de recompensa'],rareRelic:['Rare relic reward','Relíquia rara de recompensa'],forgeRelic:['Replacement relic','Relíquia substituta']};
function fieldLabel(k,value){if(!value)return L('Choose…','Escolher…');if(['card','upgrade','target1','target2','curse'].includes(k)){const c=G.card(S,value);return c?name(c)+' · '+(C.isCurse(c)?L('Curse','Maldição'):'↑'+c.level):L('Choose…','Escolher…');}if(k.toLowerCase().includes('relic')){const r=G.ARTIFACTS.find(r=>r.id===value);return r?relicTitle(r):L('Choose…','Escolher…');}return G.BY[value]?.name||value;}
const reasons={selection:['Choose the required rewards and costs.','Escolha as recompensas e os custos indicados.'],gold:['Not enough gold.','Ouro insuficiente.'],relic:['Requires an owned relic.','Exige uma relíquia própria.'],distinct:['Choose different cards.','Escolha cartas diferentes.'],copies:['Maximum of 4 copies reached.','Limite de 4 cópias atingido.'],last:['Keep at least one unit in the deck.','Mantenha ao menos uma unidade no deck.'],late:['No later quest destination available.','Não há destino posterior para a missão.']};
function consequence(id,code){const type=id==='cofre'&&code==='risk'?'chains':id==='dojo'&&code==='risk'?'omen':id==='reflexos'&&code==='risk'?'burden':id==='sombras'?(code==='gold'?'burden':'exhaustion'):id==='chave'&&code==='risk'?'chains':null;if(!type)return '';const c=C.curses[type];return '<aside class="content-consequence"><div>'+cardFace({uid:'curse-preview-'+type,type,level:0},'content-curse-preview','data-type="'+type+'"')+'</div><section><b>'+L('Negative card: ','Carta negativa: ')+esc(txt(c))+'</b><p>'+esc(L(c.enDesc,c.ptDesc))+'</p><small>'+L('Added only if the stated curse outcome occurs. Run deck only.','Adicionada apenas se ocorrer o resultado de maldição indicado. Só no deck da run.')+'</small></section></aside>';}
function eventScreen(){const ev=S.offers.content,id=S.offers.eventId,ops=C.options(S);ev.option=ops.some(o=>o.code===ev.option)?ev.option:ops[0]?.code;const o=ops.find(o=>o.code===ev.option),why=o?C.reason(S,o):'selection',quest=id==='quest_end',arena=ev.stage==='arenaOffer';const art=PA['event_'+id]||PA['event_'+({reflexos:'santuario',purificacao:'altar',arena:'camara',sombras:'mercador',banquete:'caravana',chave:'resgate',quest_end:'tesouro'}[id])];
 const cardSummary=()=>{const x=ev.selection;if(id==='santuario'&&x.relic&&x.recruit&&x.recruit2&&x.recruit!==x.recruit2){const r=G.ARTIFACTS.find(r=>r.id===x.relic),a=G.BY[x.recruit].cost*4,b=G.BY[x.recruit2].cost*4;return '<p class="content-value">'+L('Shop values: ','Valores na loja: ')+r.price+' → '+a+' + '+b+' + '+Math.max(0,r.price-a-b)+L(' gold compensation.',' ouros de compensação.')+'</p>';}return '';};
 show(runHeader(L('Event','Evento'))+'<section class="content-event"><h2>'+esc(title(id))+'</h2>'+(art?'<img class="content-event-art" src="'+art+'" alt="">':'')+(S.offers.resolved?'<div class="content-result"><b>✧ '+L('Outcome','Resultado')+'</b><p>'+esc(txt(ev.result))+'</p>'+receipt(ev)+'</div>':'<p class="content-story">'+esc(L(...stories[id]))+'</p>'+(arena?'<p class="content-value">'+L('First victory secured. Your 15-gold purse is at stake.','Primeira vitória garantida. A bolsa de 15 ouros está em jogo.')+'</p>':'')+'<div class="content-options">'+ops.map((v,i)=>'<button class="content-option '+(v.code===ev.option?'chosen':'')+'" data-act="content-option" data-id="'+v.code+'" aria-pressed="'+(v.code===ev.option)+'"><span class="content-option-number">'+(i+1)+'</span><span>'+esc(txt(v))+'<small>◈ '+(v.cost===null?L('Choose a card to see cost','Escolha a carta para ver custo'):v.cost===0?L('No gold cost','Sem custo em ouro'):v.cost+' '+L('gold','ouros'))+'</small></span><b>'+(v.code===ev.option?'◆':'◇')+'</b></button>').join('')+'</div>'+(o?'<div class="content-fields">'+o.fields.map(k=>'<label>'+L(...fields[k])+'<button class="secondary" data-act="content-picker" data-key="'+k+'">'+esc(fieldLabel(k,ev.selection[k]))+' <span>›</span></button></label>').join('')+'</div>':'')+consequence(id,ev.option)+cardSummary()+(why?'<p class="content-reason">'+L(...(reasons[why]||reasons.selection))+'</p>':''))+'</section><div class="training-sticky content-event-footer">'+(S.offers.resolved?metaButton('content-continue',L('Continue journey','Continuar viagem'),'','primary'):metaButton('content-confirm',L('Confirm choice','Confirmar escolha'),why?'disabled':'','primary')+(!quest&&!arena?metaButton('content-refuse',L('Decline','Recusar')):''))+'</div>');}
function snapshot(){return {gold:S.gold,cards:S.cards.map(c=>({...c})),relics:G.ownedRelics(S)};}
function receipt(ev){const b=ev.before;if(!b)return'';const additions=S.cards.filter(c=>!b.cards.some(x=>x.uid===c.uid)),upgrades=S.cards.filter(c=>b.cards.some(x=>x.uid===c.uid&&x.level<c.level)),removed=b.cards.filter(c=>!S.cards.some(x=>x.uid===c.uid)),relic=ev.awardedRelic||S.pendingRelic?.id;return '<ul class="content-receipt">'+(S.gold!==b.gold?'<li>◈ '+(S.gold>b.gold?'+':'')+(S.gold-b.gold)+' '+L('gold (net)','ouros (saldo)')+'</li>':'')+additions.map(c=>'<li>+ '+esc(name(c))+(c.level?' · ↑'+c.level:'')+'</li>').join('')+upgrades.map(c=>'<li>↑ '+esc(name(c))+' · '+c.level+'</li>').join('')+removed.map(c=>'<li>− '+esc(name(c))+'</li>').join('')+(relic?'<li>'+L('Relic offered: ','Relíquia oferecida: ')+esc(relicTitle(G.ARTIFACTS.find(r=>r.id===relic)))+'</li>':'')+'</ul>';}
const eventBase=eventView;eventView=function(){return S.offers?.content?eventScreen():eventBase();};
function picker(k){const ids=C.pickList(S,k),isRelic=k.toLowerCase().includes('relic'),isUid=['card','upgrade','target1','target2','curse'].includes(k);const body=ids.length?isRelic?'<div class="stack">'+ids.map(id=>{const r=G.ARTIFACTS.find(a=>a.id===id);return '<button class="offer content-relic-choice" data-act="content-pick" data-key="'+k+'" data-id="'+id+'">'+relicIcon(id)+'<span><b>'+esc(relicTitle(r))+'</b><small>'+esc(relicDescription(r))+'</small>'+relicStamp(id,S)+'<small>◈ '+r.price+' · '+rarityLabel(r.rarity)+'</small></span></button>';}).join('')+'</div>':'<div class="content-card-grid">'+ids.map(id=>{const c=isUid?G.card(S,id):{uid:id,type:id,level:k==='rareRecruit'?1:0};return '<article>'+cardFace(c,'content-pick','data-key="'+k+'"',S)+'<small>'+((k==='card'||k==='upgrade')?L('Shop value ','Valor de loja ')+C.unitValue(c)+' ◈':isUid?'':runCopiesLabel(c.type))+'</small></article>';}).join('')+'</div>':'<p>'+L('No eligible options. Try the other choice.','Sem opções elegíveis. Experimente a outra escolha.')+'</p>';journeyPanel(L(...fields[k]),body,metaButton('close',L('Back','Voltar')));}
function standardPicker(){journeyPanel(L('Captain’s Standard','Estandarte do capitão'),'<p>'+L('Choose one physical copy. It will lead the first hand of each encounter while this relic is equipped.','Escolha uma cópia física. Ela estará na primeira mão de cada confronto enquanto a relíquia estiver equipada.')+'</p><div class="content-card-grid">'+C.units(S).map(c=>cardFace(c,'content-standard-pick')).join('')+'</div>',metaButton('bag-return',L('Back to bag','Voltar à bolsa')));}
const bagBase=bagView;bagView=function(...args){bagBase(...args);const d=document.querySelector('.bag-detail'),t=C.state(S),r=bagDraft?.find(x=>x.key===bagSelected);if(r?.id==='captain_standard')d?.insertAdjacentHTML('beforeend','<p>'+L('Bound copy: ','Cópia vinculada: ')+esc(G.card(S,t.standard)?fieldLabel('card',t.standard):L('Automatic first unit','Primeira unidade automática'))+'</p>'+(!battle?metaButton('content-standard',L('Choose opening card','Escolher carta inicial')):''));if(r?.id==='dormant_sword')d?.insertAdjacentHTML('beforeend','<p class="content-value">'+((t.sword||0)>=2?L('Awakened · +12% ATK','Desperta · +12% ATQ'):(t.sword||0)+'/2 '+L('elite victories · +3% ATK','vitórias de elite · +3% ATQ'))+'</p>');};
shopServiceView=function(kind){const eligible=S.cards.filter(c=>kind==='remove'?(C.isCurse(c)||C.units(S).length>1):!C.isCurse(c)&&c.level<2);journeyPanel(kind==='remove'?L('Remove a run card','Remover carta da run'):L('Upgrade a unit','Melhorar unidade'),'<p>◈ '+S.gold+(kind==='remove'?' · '+L('Curse removal: 40 gold each.','Remover maldição: 40 ouros cada.'):'')+'</p><div class="content-service-list">'+eligible.map(c=>'<button class="offer" data-act="service-confirm" data-kind="'+kind+'" data-id="'+c.uid+'">'+P.portrait(c.type)+'<span>'+esc(name(c))+'<small>'+(C.isCurse(c)?L('Run curse','Maldição da run'):'↑'+c.level)+'</small></span><b>◈ '+G.price(S,kind,c.uid)+'</b></button>').join('')+'</div>',metaButton('close',L('Back','Voltar')));};
serviceConfirm=function(kind,uid){const c=G.card(S,uid);if(!c)return;const amount=G.price(S,kind,uid);journeyPanel((kind==='upgrade'?L('Upgrade ','Melhorar '):L('Remove ','Remover '))+name(c)+'?', '<p>'+L('Gold: ','Ouro: ')+S.gold+'</p><p>'+(kind==='upgrade'?L('Upgrade this physical copy.','Melhorar esta cópia física.'):L('Permanently remove this copy from the current run deck.','Remover esta cópia do deck da run atual.'))+'</p>',metaButton('buy-service',L('Confirm · ','Confirmar · ')+'◈ '+amount,'data-kind="'+kind+'" data-id="'+uid+'" '+(S.gold<amount?'disabled':''),'primary')+metaButton('close',L('Back','Voltar')));};
const prepBase=prep;prep=function(){prepBase();if(C.stuck(S)){const b=document.querySelector('[data-act="fight"]');if(b){b.disabled=false;b.dataset.act='content-concede';b.textContent=L('Concede round','Conceder rodada');}}const lost=S.content?.exhaustionLost||0;if(lost){const label=document.querySelector('.hand-tools>span');if(label)label.textContent=L('Exhaustion: −','Exaustão: −')+lost+' ⚡';}if(C.omens(S)){const hint=document.querySelector('.compact-hint');if(hint)hint.textContent=L('Ill Omen · field limit ','Mau Presságio · limite em campo ')+G.maxUnits(S);}};
const baseMap=mapView;mapView=function(){baseMap();const m=S.content?.mission;if(!m)return;const map=document.querySelector('.act-map');map?.insertAdjacentHTML('afterbegin','<button class="content-mission" data-act="content-mission">⚿ '+L('Prisoner’s key · Map ','Chave do prisioneiro · Mapa ')+m.act+' · '+L('Layer ','Camada ')+(m.layer+1)+' ›</button>');if(ACT_NOW()===m.act){for(const n of S.map[m.layer]||[]){const el=document.querySelector('[data-act="node"][data-id="'+n.id+'"]')||document.querySelector('[data-act="enter"][data-id="'+n.id+'"]');if(el){el.classList.add('content-quest-node');el.setAttribute('aria-label',L('Quest destination','Destino da missão'));}}}};
function ACT_NOW(){return JourneyActs.act(S);}
const pileIds=CycleData.ids,pileCards=CycleData.cards;CycleData.ids=function(s,k){return k==='exiled'?[...(s.content?.exiled||[])]:pileIds(s,k);};CycleData.cards=function(s,k){return k==='exiled'?CycleData.ids(s,k).map(id=>({...G.card(s,id)})):pileCards(s,k);};
const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),d=el?.dataset;if(!d)return guard(e);if(d.act==='hand'&&C.isCurse(G.card(S,d.id))){if(e.type==='click'){e.preventDefault();e.stopImmediatePropagation();curseDetail(G.card(S,d.id));return true;}return guard(e);}if(!d.act.startsWith('content-'))return guard(e);if(e.type!=='click'&&!(e.type==='keydown'&&['Enter',' '].includes(e.key)))return guard(e);e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return true;
 if(d.act==='content-option'){S.offers.content.option=d.id;save();eventScreen();}
 else if(d.act==='content-picker')picker(d.key);
 else if(d.act==='content-curse-preview')curseDetail({uid:'preview',type:d.type,level:0});
 else if(d.act==='content-pick'){if(C.select(S,d.key,d.id)){closeModal();save();eventScreen();}}
 else if(d.act==='content-confirm'){const ev=S.offers.content;ev.before=snapshot();if(C.accept(S,ev.option)){selected=null;save();render();}}
 else if(d.act==='content-refuse'||d.act==='content-continue'){if(G.leave(S)){save();render();}}
 else if(d.act==='content-discard'||d.act==='content-chain'){if(C.discard(S,d.id,d.act==='content-chain')){closeModal();save();render();}}
 else if(d.act==='content-standard')standardPicker();
 else if(d.act==='content-standard-pick'){if(C.setStandard(S,d.id)){save();bagView(false);}}
 else if(d.act==='content-mission'){const m=S.content.mission;journeyPanel(L('Prisoner’s key','Chave do prisioneiro'),'<p>'+L('Mission inventory · outside the deck. At map ','Inventário de missão · fora do deck. No mapa ')+m.act+', '+L('layer ','camada ')+(m.layer+1)+L(', enter any node to resolve this mission before that node. Choose a rare upgrade-1 recruit or a rare relic. The key is consumed.',' entre em qualquer node para resolver esta missão antes dele. Escolha recruta raro upgrade 1 ou relíquia rara. A chave é consumida.')+'</p>',metaButton('close',L('Back','Voltar')));}
 else if(d.act==='content-concede')journeyPanel(L('Concede this round?','Conceder esta rodada?'),'<p>'+L('Your curses left no playable formation. This counts as a round loss. Losing the encounter ends the run.','Suas maldições deixaram você sem formação jogável. Isso conta como derrota na rodada. Perder o confronto encerra a run.')+'</p>',metaButton('content-concede-confirm',L('Concede round','Conceder rodada'),'','primary')+metaButton('close',L('Back','Voltar')));
 else if(d.act==='content-concede-confirm'){if(C.concede(S)){closeModal();save();render();}}return true;};
})();
